// === Tab: mySketch ===
// Refraction 💎 #WCCChallenge

let junction
async function setup() {
	createCanvas(1200, 600)
	colorMode(HSB)
	angleMode(DEGREES)
	background(0, 0, 0)

	junction = height / 3 //floor(height / 2 + random(-100, 100))

	for (let tm = 0; tm < 10; tm++) {
		maxLen = floor(sqrt(width * width + height * height))
		halfMaxLen = floor(maxLen / 2)

		// draw point
		junction = floor(random(height*0.9)) // mouse

		let tx = width / 2
		let ty = height / 2
		translate(tx, ty)
		rotate(random(360))

		stroke(0, 0, 100)
		line(
			-halfMaxLen,
			-halfMaxLen + junction,
			halfMaxLen,
			-halfMaxLen + junction
		)

		let ls = random(0.5, 0.75) // speed of light in slow medium, 0.66 glass, 0.75 water
		let ray = { fromX: 0, toX: 0 }
		let ref = { fromX: 0, toX: 0 }
		ray.fromX = -halfMaxLen + floor(random(width)) // mouse
		ray.toX = -halfMaxLen + halfMaxLen
		let opp = ray.toX - ray.fromX
		let adj = junction
		let angle = atan2(opp, adj)

		ref.fromX = ray.toX
		ref.toX = ref.fromX + (height - adj) * tan(angle * ls)

		let amount = random([5, 10, 15, 20, 25])
		let sd = random([1, 3, 5, 7, 9, 11])

		for (let y = -halfMaxLen; y < -halfMaxLen + junction; y++) {
			const x = map(y, -halfMaxLen, -halfMaxLen + junction, ray.fromX, ray.toX)
			stroke(0, 0, 100)
			light(x, y, amount, sd)
			//await sleep(1)
		}

		let minWei = 0.7 // the purple light
		let weiStep = (1 - minWei) / amount
		let lineAmount = amount
		for (let y = -halfMaxLen + junction; y <= halfMaxLen; y++) {
			let wei = 1
			for (let n = 0; n < lineAmount; n++) {
				ref.toX = ref.fromX + (height - adj) * tan(angle * ls * wei)
				var x = map(y, -halfMaxLen + junction, halfMaxLen, ref.fromX, ref.toX)
				const h = map(wei, 1, minWei, 0, 270)
				const s =
					map(y, -halfMaxLen + junction, halfMaxLen, 0, 100) * (abs(angle) / 45)
				stroke(h, s, 100)
				light(x, y, 1, sd)
				wei -= weiStep
			}
		}
		await sleep(100)
	}
}

function draw() {}

function light(x, y, amount, sd) {
	for (let i = 0; i < amount; i++) {
		point(randomGaussian(x, sd), y)
	}
}

function sleep(ms) {
	return new Promise((resolve) => setTimeout(resolve, ms))
}

